    const val FATIHA = "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَٰنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ"
    const val AYAT_KURSI = "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ"
    const val AYAT_KURSI_FA = "خداست که هیچ معبودی جز او نیست؛ زنده و برپادارنده است. نه خوابِ سبک او را فرا می‌گیرد و نه خواب سنگین. آنچه در آسمان‌ها و زمین است از آنِ اوست. کیست که جز به اذن او نزدش شفاعت کند؟ آنچه پیش روی آنان و پشت سرشان است می‌داند و آنان جز به آنچه او بخواهد به چیزی از علمش احاطه نمی‌یابند. کرسی او آسمان‌ها و زمین را فرا گرفته و نگهداری آن دو بر او دشوار نیست، و او بلندمرتبه و بزرگ است."
    const val IKHLAS = "قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ"
    const val IKHLAS_FA = "بگو: او خدای یکتاست؛ خدا بی‌نیاز است؛ نه زاده و نه زاده شده است؛ و هیچ‌کس همتای او نیست."
    const val FALAQ = "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ مِنْ شَرِّ مَا خَلَقَ ۝ وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝ وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ۝ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ"
    const val FALAQ_FA = "بگو: به پروردگار سپیده‌دم پناه می‌برم؛ از شر آنچه آفریده است؛ و از شر تاریکی هنگامی که فراگیرد؛ و از شر دمندگان در گره‌ها؛ و از شر حسود هنگامی که حسد ورزد."
    const val NAS = "قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَٰهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ۝ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ۝ مِنَ الْجِنَّةِ وَالنَّاسِ"
    const val NAS_FA = "بگو: به پروردگار مردم پناه می‌برم؛ فرمانروای مردم؛ معبود مردم؛ از شر وسوسه‌گر پنهان‌شونده؛ همان که در سینه‌های مردم وسوسه می‌کند؛ چه از جن و چه از انسان."
    const val BAQARAH_END = "آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۝ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ"
    const val BAQARAH_END_FA = "پیامبر به آنچه از سوی پروردگارش بر او نازل شده ایمان آورده و مؤمنان نیز همگی به خدا، فرشتگان، کتاب‌ها و پیامبرانش ایمان آورده‌اند و میان هیچ‌یک از پیامبرانش فرق نمی‌گذارند. گفتند: شنیدیم و اطاعت کردیم؛ پروردگارا، آمرزش تو را می‌خواهیم و بازگشت به سوی توست. خدا هیچ‌کس را جز به اندازه توانش تکلیف نمی‌کند. هر کار نیکی انجام دهد به سود او و هر بدی کند به زیان اوست. پروردگارا، اگر فراموش کردیم یا خطا کردیم ما را مؤاخذه مکن؛ بار سنگینی چون پیشینیان بر ما مگذار؛ آنچه توانش را نداریم بر ما تحمیل مکن؛ از ما درگذر، ما را بیامرز و بر ما رحم کن؛ تو سرپرست مایی، پس ما را یاری فرما."

