    fun dailyPrayer(dayOfWeek:Int): Triple<String,String,String> = when(dayOfWeek){
        7 -> Triple("شنبه", "دعای آغاز هفته", "خدایا این هفته را برای ما سرشار از خیر، آرامش و عاقبت‌به‌خیری قرار ده.")
        1 -> Triple("یکشنبه", "دعای گشایش", "خدایا درهای رحمت و گشایش را به روی ما بگشا و دل ما را به یاد خود آرام کن.")
        2 -> Triple("دوشنبه", "دعای حاجت", "پروردگارا حاجت‌های خیر ما را برآورده کن و آنچه صلاح ماست برایمان مقدر فرما.")
        3 -> Triple("سه‌شنبه", "دعای رحمت", "ای مهربان‌ترین مهربانان، ما و خانواده‌مان را در پناه رحمت و لطف خود قرار ده.")
        4 -> Triple("چهارشنبه", "دعای آرامش", "خدایا به دل‌های ما آرامش، به کارهای ما برکت و به قدم‌هایمان استواری عطا کن.")
        5 -> Triple("پنجشنبه", "دعای درگذشتگان", "خدایا پدر و مادر ما و همه درگذشتگان را مشمول رحمت و آمرزش خود قرار ده.")
        else -> Triple("جمعه", "دعای روز جمعه", "خدایا این جمعه را برای ما روز رحمت، آمرزش، سلامتی و خیر قرار ده و دعاهای خیرمان را بپذیر.")
    }

    fun dailyDhikr(dayOfWeek:Int): Pair<String,String> = when(dayOfWeek){
        7 -> "شنبه" to "یا رَبَّ الْعالَمین"
        1 -> "یکشنبه" to "یا ذَا الْجَلالِ وَ الْإِکْرام"
        2 -> "دوشنبه" to "یا قاضِیَ الْحاجات"
        3 -> "سه‌شنبه" to "یا أَرْحَمَ الرّاحِمین"
        4 -> "چهارشنبه" to "یا حَیُّ یا قَیّوم"
        5 -> "پنجشنبه" to "لا إلهَ إلّا اللهُ الْمَلِکُ الْحَقُّ الْمُبین"
        else -> "جمعه" to "اللهم صل علی محمد و آل محمد"
    }
